    /*
     * Add to the Facilities
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	MedicalSupplier
     */
    public MedicalSupplier addToFacilities( UUID parentId, Facility addTo ) {
	    LOGGER.info("handling AssignFacilitiesToMedicalSupplierEvent - " );
	    
	    MedicalSupplier parentEntity = repository.findById(parentId).get();
	    Facility child = registry.project( Facility.class, addTo.getFacilityId());
	    
	    parentEntity.getFacilities().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Facilities
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	MedicalSupplier
     */
	public MedicalSupplier removeFromFacilities( UUID parentId, Facility removeFrom ) {
	    LOGGER.info("handling RemoveFacilitiesFromMedicalSupplierEvent " );
	
	    MedicalSupplier parentEntity = repository.findById(parentId).get();
	    Facility child = registry.project( Facility.class, removeFrom.getFacilityId());
	    
	    parentEntity.getFacilities().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

